RefreshBtn.onClick:
(e, el, s) => {
        s.root.update({ isLoading: true });
        setTimeout(() => {
          s.root.update({ isLoading: false });
        }, 800);
      }

ExecutionStatusToggle.onClick:
(e, el, s) => {
    var cycle = { passed: "failed", failed: "blocked", blocked: "skipped", skipped: "passed", untested: "passed" };
    var nextStatus = cycle[s.status] || "passed";
    el.call("toggleTestStatus", s.id, nextStatus);
  }

SelectAllCheckbox.checked:
(el, s) => {
          var runs = s.root.testRuns || [];
          var selected = s.root.selectedTestIds || [];
          return runs.length > 0 && selected.length === runs.length;
        }

RunStatusBadge.isDegraded:
(el, s) => {
        var m = el.call("computeMetrics");
        return m.passRate >= 50 && m.passRate < 80;
      }

StatusText.text:
(el, s) => {
          var m = el.call("computeMetrics");
          if (m.passRate >= 80) return "Healthy";
          if (m.passRate >= 50) return "Degraded";
          return "Critical";
        }

PassRateLarge.isPassMid:
(el, s) => {
        var r = el.call("computeMetrics").passRate;
        return r >= 50 && r < 80;
      }

ViewLogBtn.onClick:
(e, el, s) => {
          e.stopPropagation();
          el.call("openLogModal", s.id, s.errorMessage);
        }

functions.applyBulkStatus:
function applyBulkStatus2(newStatus) {
  const rootEl = this.getRoot();
  const rootState = rootEl.state;
  if (!rootState) return;
  const selected = rootState.selectedTestIds || [];
  if (selected.length === 0) return;
  rootState.update({ bulkLoading: true });
  const runs = (rootState.testRuns || []).map(function(r) {
    return selected.includes(r.id) ? Object.assign({}, r, { status: newStatus }) : r;
  });
  rootState.update({ testRuns: runs });
  setTimeout(function() {
    rootEl.state.update({
      bulkLoading: false,
      selectedTestIds: [],
      toastMessage: selected.length + " tests marked as " + newStatus,
      toastType: "success"
    });
    setTimeout(function() {
      rootEl.state.update({ toastMessage: null });
    }, 3e3);
  }, 600);
}

functions.closeLogModal:
function closeLogModal2() {
  var rootState = this.getRoot().state;
  if (!rootState) return;
  rootState.update({
    logModalOpen: false,
    logModalTestId: null,
    logModalContent: null
  });
}

functions.computeMetrics:
function computeMetrics2() {
  const rootState = this.getRoot().state;
  const runs = rootState && rootState.testRuns ? rootState.testRuns : [];
  const total = runs.length;
  if (total === 0) return { passed: 0, failed: 0, blocked: 0, skipped: 0, total: 0, passRate: 0, failRate: 0, blockedRate: 0, skippedRate: 0 };
  const passed = runs.filter((r) => r.status === "passed").length;
  const failed = runs.filter((r) => r.status === "failed").length;
  const blocked = runs.filter((r) => r.status === "blocked").length;
  const skipped = runs.filter((r) => r.status === "skipped").length;
  return {
    total,
    passed,
    failed,
    blocked,
    skipped,
    passRate: Math.round(passed / total * 100),
    failRate: Math.round(failed / total * 100),
    blockedRate: Math.round(blocked / total * 100),
    skippedRate: Math.round(skipped / total * 100)
  };
}

functions.formatDuration:
function formatDuration2(ms) {
  if (!ms || ms === 0) return "\u2014";
  if (ms < 1e3) return ms + "ms";
  var s = (ms / 1e3).toFixed(1);
  return s + "s";
}

functions.getStatusIcon:
function getStatusIcon2(status) {
  var icons = {
    passed: "checkCircle",
    failed: "xCircle",
    blocked: "alertCircle",
    skipped: "minusCircle",
    untested: "minusCircle"
  };
  return icons[status] || "minusCircle";
}

functions.getStatusLabel:
function getStatusLabel2(status) {
  var labels = {
    passed: "Pass",
    failed: "Fail",
    blocked: "Blocked",
    skipped: "Skipped",
    untested: "Untested"
  };
  return labels[status] || "Unknown";
}

functions.openLogModal:
function openLogModal2(testId, errorMessage) {
  var rootState = this.getRoot().state;
  if (!rootState) return;
  rootState.update({
    logModalOpen: true,
    logModalTestId: testId,
    logModalContent: errorMessage || "No error log available for this test run."
  });
}

functions.toggleRowExpand:
function toggleRowExpand2(testId) {
  const rootState = this.getRoot().state;
  if (!rootState) return;
  const expanded = rootState.expandedTestIds || [];
  const isExpanded = expanded.includes(testId);
  if (isExpanded) {
    rootState.update({ expandedTestIds: expanded.filter((id) => id !== testId) });
  } else {
    rootState.update({ expandedTestIds: expanded.concat([testId]) });
  }
}

functions.toggleSelectAll:
function toggleSelectAll2() {
  var rootState = this.getRoot().state;
  if (!rootState) return;
  var runs = rootState.testRuns || [];
  var selected = rootState.selectedTestIds || [];
  var allSelected = selected.length === runs.length;
  if (allSelected) {
    rootState.update({ selectedTestIds: [] });
  } else {
    rootState.update({ selectedTestIds: runs.map(function(r) {
      return r.id;
    }) });
  }
}

functions.toggleSelectTest:
function toggleSelectTest2(testId) {
  var rootState = this.getRoot().state;
  if (!rootState) return;
  var selected = rootState.selectedTestIds || [];
  var isSelected = selected.includes(testId);
  if (isSelected) {
    rootState.update({ selectedTestIds: selected.filter(function(id) {
      return id !== testId;
    }) });
  } else {
    rootState.update({ selectedTestIds: selected.concat([testId]) });
  }
}

functions.toggleTestStatus:
function toggleTestStatus2(testId, newStatus) {
  const rootEl = this.getRoot();
  const rootState = rootEl.state;
  if (!rootState) return;
  const runs = rootState.testRuns || [];
  const idx = runs.findIndex((r) => r.id === testId);
  if (idx === -1) return;
  const prevStatus = runs[idx].status;
  const updatedRuns = runs.map(
    (r, i) => i === idx ? Object.assign({}, r, { status: newStatus }) : r
  );
  rootState.update({ testRuns: updatedRuns });
  const self = rootEl;
  setTimeout(() => {
    const apiFailed = Math.random() < 0.1;
    if (apiFailed) {
      const currentState = self.state;
      const currentRuns = currentState.testRuns || [];
      const revertedRuns = currentRuns.map(
        (r, i) => i === idx ? Object.assign({}, r, { status: prevStatus }) : r
      );
      currentState.update({
        testRuns: revertedRuns,
        toastMessage: "Failed to update status \u2014 reverted",
        toastType: "error"
      });
      setTimeout(() => {
        self.state.update({ toastMessage: null });
      }, 4e3);
    }
  }, 300);
}
